var a=`1073-pork-adobo`;var n=`world-1073`;var t=`PH`;var r=`southeast-asia`;var o=4;var s=141;var d={en:`Pork Adobo`,ua:`Свинина адобо`};var u={en:`Pork Adobo is a dish from Philippines prepared with pork shoulder, light soy sauce, white vinegar, garlic. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Свинина адобо, страва кухні країни Філіппіни, яку готують із таких продуктів: свиняча лопатка, світлий соєвий соус, білий оцет, часник. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var l=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 45 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 45 хвилин.`,t:[`marinating`],m:45,i:[[`pork-shoulder`,900,`g`],[`light-soy-sauce`,90,`ml`],[`white-vinegar`,110,`ml`],[`garlic`,8,`clove`],[`bay-leaf`,3,`leaf`],[`black-peppercorn`,8,`pcs`]]},{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`canola-oil`,35,`ml`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 75 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 75 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:75,i:[[`water`,370,`ml`]]},{en:`Simmer the liquid and flavorings uncovered for about 9 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 9 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:9,i:[[`brown-sugar`,20,`g`]]}];var g={slug:a,id:n,country:`PH`,region:r,servings:4,minutes:141,title:d,text:u,steps:l};export{t as country,g as default,n as id,s as minutes,r as region,o as servings,a as slug,l as steps,u as text,d as title};